before = list.sort_by(before_all, "at", "desc")
chosen = before[0] if before != [] else fail("NO_DEPLOY", "no deploy before spike")

owner = boundary retry 2 { return get_service_owners({ service: top.service }) } catch err {
    return fail("OWNER_FAILED", err.code + ": " + err.message)
}

return {
    top_service: top.service,
    spike_start: time.format(spike_start),
    chosen_sha: chosen.sha,
    chosen_deployed_at: chosen.deployed_at,
    owner_email: owner.owner_email,
    stats: for s in ranked { return { service: s.service, total: s.total, counts: s.counts, maxw: s.maxw, ratio: s.ratio } },
    hours: for h in hours { return { hour: h.hour, count: h.count } },
    deploys: parsed
}
